contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint balBeforeC = address(c).balance;
        uint balBeforeThis = address(this).balance;
        bool reverted;
        c.sendTo(address(this), amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted ? (address(c).balance == balBeforeC)
                        : (amount <= balBeforeC && address(this).balance == balBeforeThis + amount));
    }
    receive() external payable {}
}

