// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        uint balBeforeC = address(c).balance;
        uint balBeforeThis = address(this).balance;
        bool reverted;
        try c.sendTo(address(this), amount) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted ? (address(c).balance == balBeforeC)
                        : (amount <= balBeforeC && address(this).balance == balBeforeThis + amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
